import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.kcd3e0J6.js";const s="/study/images/assets/asset-worker-handoff.svg",u=JSON.parse('{"title":"ワーカーが準備したアセットを描画側へ渡す","description":"","frontmatter":{"title":"ワーカーが準備したアセットを描画側へ渡す","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"アセット要求と準備結果を別々のキューで渡す。世代照合、キューとメモリの予算、登録とGPU転送、終了時の回収を扱う。","aliases":["asset worker","アセットワーカー","asset handoff","結果キュー","generation token","世代照合","CPU Ready","backpressure","登録予算"],"verification":"MicrosoftのWindows I/O・D3D12資料とUnityのスレッド切り替え仕様に照合（2026-11-06）"}},"headers":[],"relativePath":"game/asset-worker-handoff.md","filePath":"game/asset-worker-handoff.md"}'),i={name:"game/asset-worker-handoff.md"};function d(n,e,h,c,l,f){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ワーカーが準備したアセットを描画側へ渡す" tabindex="-1">ワーカーが準備したアセットを描画側へ渡す <a class="header-anchor" href="#ワーカーが準備したアセットを描画側へ渡す" aria-label="Permalink to &quot;ワーカーが準備したアセットを描画側へ渡す&quot;">​</a></h1><p>ゲームが次の部屋のメッシュを要求すると、ワーカーがファイルを読み、データを展開し、頂点とインデックスを検査します。準備済みのデータを結果キューに渡し、描画側が自分の処理時間に合わせて取り出します。この構成では、要求の現在世代と公開済みのハンドルを、登録を担当するスレッドだけが更新します。<a href="/study/game/asset-loading.html">ゲームのアセットロード設計</a> · <a href="/study/graphics/mesh/gltf-mesh-buffers.html">glTFのメッシュデータ</a></p><figure class="study-figure"><img src="'+s+'" alt="登録側がアセットIDと世代を付けて要求を出し、ワーカーが読み取り・展開・検査を行って結果キューに渡す。登録側が結果を取り出し、現在の要求と照合する。古い結果は回収し、有効な結果はGPU転送と同期を経て描画に公開する。" width="760" height="560" loading="lazy"><figcaption>要求キューと結果キューで受け渡しを行い、登録側が結果を採用するか決めます。<a href="/study/images/assets/asset-worker-handoff.svg" target="_blank" rel="noopener noreferrer">ワーカーから描画への受け渡し図を拡大</a></figcaption></figure><h2 id="キューを境にデータの持ち主を変える" tabindex="-1">キューを境にデータの持ち主を変える <a class="header-anchor" href="#キューを境にデータの持ち主を変える" aria-label="Permalink to &quot;キューを境にデータの持ち主を変える&quot;">​</a></h2><table tabindex="0"><thead><tr><th>境界</th><th>渡すもの</th><th>受け取った側の仕事</th></tr></thead><tbody><tr><td>要求キュー</td><td>アセットID、要求世代、読み取り範囲、検査に必要な形式情報</td><td>ワーカーがファイルを読み、範囲やサイズを検査してデコードする</td></tr><tr><td>結果キュー</td><td>アセットID、要求世代、検査済みのCPUデータ、または失敗の理由</td><td>登録側が現在の要求と照合し、次の処理か回収に進む</td></tr><tr><td>GPUへ転送</td><td>転送用の領域、転送先リソース、コピー完了を示すフェンス値</td><td>登録側が描画に必要な依存と順序を確認し、利用側にハンドルを公開する</td></tr></tbody></table><p>ワーカーは結果を組み立ててからキューへ入れます。例えば頂点の <code>std::vector</code> を結果の一部としてムーブし、キューを経由して取り出した側が保持します。同じ領域を指すポインターをワーカーに残して書き足すと、登録側とアクセスが重なります。ミューテックスで守る範囲はキューの追加・取り出しと状態の更新に絞り、読み取りやデコード、エンジンへの登録はその外で行います。<a href="https://eel.is/c++draft/thread.mutex.requirements" target="_blank" rel="noreferrer">C++作業草案のミューテックス要件</a> · <a href="/study/runtime/bounded-worker-queues.html">上限付きワーカーキュー</a></p><p>登録に使うAPIには、それを呼べるスレッドの条件があります。例えばUnityでメインスレッドを要求するAPIを使う場合、バックグラウンドで準備した結果を <code>Awaitable.MainThreadAsync</code> などでメインスレッドへ戻してから登録します。D3D12で複数スレッドからコマンドを記録する構成では、リストとアロケータの使用条件に合わせて仕事を割り当てます。<a href="https://docs.unity3d.com/6000.0/Documentation/ScriptReference/Awaitable.MainThreadAsync.html" target="_blank" rel="noreferrer">Unityのメインスレッドへの切り替え</a> · <a href="/study/graphics/optimization/parallel-command-recording.html">D3D12のコマンドの並列記録</a></p><h2 id="受け取った結果が今も必要か確かめる" tabindex="-1">受け取った結果が今も必要か確かめる <a class="header-anchor" href="#受け取った結果が今も必要か確かめる" aria-label="Permalink to &quot;受け取った結果が今も必要か確かめる&quot;">​</a></h2><p>例えば <code>mesh A</code> の世代7を処理中に部屋を移動し、同じIDで世代8を要求します。先に世代8が届いたら登録を進めます。後から世代7が届いたら、同じIDでも現在世代と合わないので、CPUデータを破棄し、使っていた予算を返します。失敗した結果にも世代を付ければ、古い失敗で新しい要求を失敗状態に変えずに済みます。<a href="/study/game/asset-loading.html">世代とアセットの寿命</a></p><p>結果を受理した後も、GPUコピーを待つ間に要求は変わり得ます。公開する直前にも現在の要求と照合します。登録側がCPUデータを転送用の領域にコピー済みなら、ほかに参照がないCPUデータを回収できます。GPUが読む転送用領域はコピーが終わるまで保持します。D3D12でコピーと描画が別キューなら、コピー側で <code>Signal</code> を入れ、描画側では対象値の <code>Wait</code> と必要なリソース状態を用意してから使います。途中で不要になった転送先も、提出済みコマンドによる最後の参照まで保持します。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/user-mode-heap-synchronization" target="_blank" rel="noreferrer">Microsoftのキュー間同期</a> · <a href="/study/graphics/optimization/gpu-resource-lifetime.html">GPUリソースの寿命とフェンス</a></p><h2 id="何件待てるか、何バイト持てるかを決める" tabindex="-1">何件待てるか、何バイト持てるかを決める <a class="header-anchor" href="#何件待てるか、何バイト持てるかを決める" aria-label="Permalink to &quot;何件待てるか、何バイト持てるかを決める&quot;">​</a></h2><p>待機中の要求数と、準備済みの結果数にそれぞれ上限を設けます。例えばワーカー2本と結果キュー3枠の構成で、各ワーカーが持つ準備済みのデータと各結果を最大4 MiBに制限すると、そのデータだけで最大20 MiBになります。読み取り中の入力、展開の作業領域、登録側が取り出した結果、GPU転送用の領域も予算に含めます。大きな確保が必要なら先に予算を取り、空きが出るまで新しい準備を遅らせます。<a href="/study/runtime/bounded-worker-queues.html">上限付きキューとバックプレッシャー</a></p><p>結果キューが満杯なら、ワーカーは現在の結果を持ったまま空きを待つか、設計で定めた優先度に沿って回収します。フレームを進めるスレッドでは、結果が届くまで待たず、たとえば登録に使える時間や転送量の範囲で取り出します。1件で転送予算を超える素材は、分割して進めるか、処理できる枠を別に設けます。記録する値をキューの滞在時間、保持バイト数、1フレームの登録時間に分けると、どこで詰まっているかを追えます。<a href="/study/graphics/texture/texture-streaming-and-mip-residency.html">テクスチャストリーミングとmipの常駐</a></p><h2 id="取り消しと終了で持ち主を失わない" tabindex="-1">取り消しと終了で持ち主を失わない <a class="header-anchor" href="#取り消しと終了で持ち主を失わない" aria-label="Permalink to &quot;取り消しと終了で持ち主を失わない&quot;">​</a></h2><p>取り消した要求は登録側で無効にし、ワーカーにも止められる作業を止めるよう伝えます。処理が既に終わりかけていれば結果は後から届きます。結果の回収は続け、採用しないデータも所有者が破棄します。例えばWindowsの <code>CancelIoEx</code> は完了を待たないため、I/Oの完了を確認するまで要求情報や読み取り先を保持します。<a href="https://learn.microsoft.com/en-us/windows/win32/api/ioapiset/nf-ioapiset-cancelioex" target="_blank" rel="noreferrer">MicrosoftのCancelIoEx仕様</a> · <a href="/study/os/cancelling-overlapped-io.html">非同期I/Oのキャンセル</a></p><p>受付を終えるときは、要求キューを閉じて待機中のワーカーを起こし、引き受け済みの処理を終わらせます。その間も登録側は結果を取り出します。結果キューが満杯のまま先にワーカーを <code>join</code> すると、ワーカーは空きを待ち、登録側はワーカーを待ち続けます。すべてのワーカーが結果の投入を終えたら結果キューを閉じ、残った結果を回収します。スレッドの終了を確認し、最後に提出済みのGPU処理が保持する資源をフェンスに従って回収します。<a href="/study/runtime/bounded-worker-queues.html">上限付きワーカーキューの終了手順</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d12/fence-based-resource-management" target="_blank" rel="noreferrer">Microsoftのフェンスによる資源管理</a></p><p>実践では、2本のワーカーが用意された頂点データからX座標の最小値と最大値を計算します。登録側は結果キューからフレームごとに最大1件を取り出し、現在世代の結果だけを公開します。実際のファイル読み取りやGPU転送は、ここで観察するCPU上の受け渡しより前後の工程です。<a href="/study/practice/threads/asset-worker-handoff-observation.html">C++でアセットの受け渡しを観察する</a></p>',17)])])}const p=a(i,[["render",d]]);export{u as __pageData,p as default};
